mapper.select:
select s.id,s.name,s.price,s.image,s.status,s.category_id,s.description,s.update_time, c.name categoryName from setmeal s
left join category c on s.category_id = c.id


        and s.name like concat('%',#{name},'%')


        and s.status = #{status}


        and s.category_id = #{categoryId}


order by s.update_time desc
